<template>
  <section class="gc-settings" aria-label="图谱配色设置" @keydown.esc="editingType=''">
    <div class="gc-heading"><div><h3>图谱配色</h3><p>同类型使用同一种颜色，点击圆形铅笔图标修改整类颜色。</p></div><button class="gc-reset" @click="$emit('reset')">恢复默认</button></div>
    <p v-if="largest" class="gc-explanation">{{largest.type}}有 {{largest.count.toLocaleString()}} 个，占全部节点 {{(largest.count/total*100).toFixed(1)}}%，因此全图中这类颜色最多。</p>
    <div class="gc-grid"><button v-for="row in counts" :key="row.type" :class="{editing:editingType===row.type}" :aria-label="'修改'+row.type+'颜色'" :aria-expanded="editingType===row.type" :title="'点击修改'+row.type+'颜色'" @click="edit(row.type)"><i class="gc-color" :style="{background:color(row.type)}"><GraphIcon name="edit"/></i><span><b>{{row.type}}</b><small>{{row.count.toLocaleString()}} 个节点</small></span></button></div>
    <div v-if="editingType" class="gc-editor" :aria-label="editingType+'配色编辑'">
      <div class="gc-editor-title"><b>修改{{editingType}}颜色</b><button aria-label="关闭颜色编辑" @click="editingType=''"><GraphIcon name="close"/></button></div>
      <div class="gc-editor-content"><div class="gc-presets"><button v-for="preset in presets" :key="preset" :style="{background:preset}" :aria-label="'使用颜色 '+preset" :title="preset" :aria-pressed="color(editingType)===preset" @click="apply(preset)"><span v-if="color(editingType)===preset">✓</span></button></div><div class="gc-custom"><label class="gc-native"><input type="color" v-model="draftColor" :aria-label="editingType+'类型颜色'"><span>自定义</span></label><input class="gc-hex" v-model="draftColor" aria-label="颜色代码" maxlength="7" placeholder="#2563eb" @keydown.enter.prevent="apply(draftColor)"><button class="gc-apply" @click="apply(draftColor)">应用颜色</button></div></div>
      <p v-if="error" role="alert" class="gc-error">{{error}}</p>
    </div>
    <p v-if="message||status" class="gc-status" role="status">{{message||status}}</p>
  </section>
</template>
<script setup>
import {ref,computed,watch} from 'vue'
import GraphIcon from './GraphIcon.vue'
import {typeColor} from './graphColorSettings.js'
const props=defineProps({counts:{type:Array,required:true},settings:{type:Object,required:true},message:String})
const emit=defineEmits(['change','reset'])
const editingType=ref(''),draftColor=ref(''),error=ref(''),status=ref('')
const total=computed(()=>props.counts.reduce((sum,row)=>sum+row.count,0)),largest=computed(()=>[...props.counts].sort((a,b)=>b.count-a.count)[0])
const color=type=>typeColor(type,props.settings)
const presets=['#2563eb','#0891b2','#16a34a','#84a315','#ef9218','#ea580c','#e55353','#db2777','#8b5acf','#4f46e5','#795548','#536579']
function edit(type){editingType.value=type;draftColor.value=color(type);error.value='';status.value=''}
watch(()=>editingType.value&&color(editingType.value),value=>{if(value)draftColor.value=value})
function apply(value){
  if(!/^#[0-9a-f]{6}$/i.test(value)){error.value='请输入完整的颜色代码，例如 #2563eb';return}
  const normalized=value.toLowerCase();draftColor.value=normalized;error.value='';emit('change',editingType.value,normalized);status.value=editingType.value+'颜色已更新，并自动保存在当前浏览器。'
}
</script>
<style scoped>
.gc-settings{padding:18px 20px;border:1px solid var(--wb-ui-border);border-radius:10px;background:var(--wb-ui-surface);margin:0 0 18px;color:var(--wb-ui-text)}.gc-settings button,.gc-settings input{font:inherit}.gc-settings button{cursor:pointer;box-shadow:none}.gc-settings button::after{display:none}.gc-heading{display:flex;align-items:center;justify-content:space-between;gap:15px}.gc-heading h3{font-size:15px;margin:0;color:var(--wb-ui-text)}.gc-heading p,.gc-explanation{font-size:var(--wb-font-meta);line-height:1.8;color:var(--wb-ui-secondary);margin:6px 0}.gc-reset,.gc-apply{border:1px solid var(--wb-ui-border);background:var(--wb-ui-surface-raised);border-radius:6px;padding:8px 12px;color:var(--wb-ui-accent);font-size:var(--wb-font-meta);white-space:nowrap}.gc-explanation{color:var(--wb-ui-secondary)}.gc-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(155px,1fr));gap:9px;margin-top:13px}.gc-grid>button{display:flex;align-items:center;gap:10px;min-width:0;text-align:left;padding:10px;border:1px solid transparent;border-radius:8px;background:transparent;color:var(--wb-ui-text)}.gc-grid>button:hover,.gc-grid>button.editing{background:var(--wb-ui-surface-raised);border-color:var(--wb-ui-border)}.gc-color{display:grid;place-items:center;width:34px;height:34px;flex-shrink:0;border-radius:50%;color:var(--wb-ui-on-primary);box-shadow:0 2px 5px #20212420}.gc-color svg{width:15px;height:15px}.gc-grid b{display:block;font-size:var(--wb-font-control);font-weight:550}.gc-grid small{display:block;font-size:var(--wb-font-meta);margin-top:4px;color:var(--wb-ui-secondary)}.gc-editor{margin-top:15px;padding:14px;background:var(--wb-ui-surface-raised);border:1px solid var(--wb-ui-border);border-radius:8px}.gc-editor-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.gc-editor-title b{font-size:var(--wb-font-control);font-weight:550;color:var(--wb-ui-secondary)}.gc-editor-title>button{display:grid;place-items:center;width:24px;height:24px;border:0;background:transparent;color:var(--wb-ui-muted)}.gc-editor-title svg{width:16px;height:16px}.gc-editor-content{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap}.gc-presets{display:flex;gap:8px;flex-wrap:wrap}.gc-presets>button{display:grid;place-items:center;width:25px;height:25px;border-radius:50%;border:2px solid var(--wb-ui-surface-raised);outline:1px solid var(--wb-ui-border);color:var(--wb-ui-on-primary);font-size:var(--wb-font-body)}.gc-presets>button[aria-pressed=true]{outline:2px solid var(--wb-ui-secondary);outline-offset:2px}.gc-custom{display:flex;align-items:center;gap:9px;flex-wrap:wrap}.gc-native{display:flex;align-items:center;gap:6px;font-size:var(--wb-font-meta);color:var(--wb-ui-secondary);cursor:pointer}.gc-native input{width:27px;height:27px;padding:0;border:0;background:transparent;cursor:pointer}.gc-hex{width:91px;border:1px solid var(--wb-ui-border);border-radius:5px;padding:7px;font-size:var(--wb-font-meta);color:var(--wb-ui-secondary);background:var(--wb-ui-surface-raised)}.gc-apply{background:var(--wb-ui-accent);border-color:var(--wb-ui-accent);color:var(--wb-ui-on-primary)}.gc-status,.gc-error{font-size:var(--wb-font-meta);line-height:1.7;margin:12px 0 0;color:var(--wb-ui-danger)}.gc-error{color:var(--wb-ui-danger)}.gc-settings button:focus-visible,.gc-settings input:focus-visible{outline:2px solid var(--wb-ui-accent);outline-offset:3px}@media(max-width:600px){.gc-settings{padding:14px}.gc-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.gc-heading{align-items:flex-start}.gc-editor-content{gap:14px}}
</style>
